  1	package money
  2	
  3	import (
  4		"errors"
  5		"fmt"
  6		"math"
  7		"strconv"
  8		"strings"
  9	)
 10	
 11	var (
 12		// ErrInvalidAmount is returned for malformed or out-of-range amounts.
 13		ErrInvalidAmount = errors.New("invalid amount")
 14		// ErrPrecision is returned when an amount has more decimals than its currency allows.
 15		ErrPrecision = errors.New("too many decimal places for currency")
 16		// ErrCurrencyMismatch is returned when combining amounts in different currencies.
 17		ErrCurrencyMismatch = errors.New("currency mismatch")
 18	)
 19	
 20	// Amount is an exact quantity of money in minor units.
 21	type Amount struct {
 22		Minor    int64
 23		Currency Currency
 24	}
 25	
 26	// New builds an amount from minor units.
 27	func New(minor int64, code string) (Amount, error) {
 28		c, err := LookupCurrency(code)
 29		if err != nil {
 30			return Amount{}, err
 31		}
 32		return Amount{Minor: minor, Currency: c}, nil
 33	}
 34	
 35	// MustNew is New for tests and constants; it panics on unknown currencies.
 36	func MustNew(minor int64, code string) Amount {
 37		a, err := New(minor, code)
 38		if err != nil {
 39			panic(err)
 40		}
 41		return a
 42	}
 43	
 44	// Parse reads a decimal string in major units ("10.50") for the given currency.
 45	// More fractional digits than the currency exponent is an error, never rounded.
 46	func Parse(s, code string) (Amount, error) {
 47		cur, err := LookupCurrency(code)
 48		if err != nil {
 49			return Amount{}, err
 50		}
 51		s = strings.TrimSpace(s)
 52		neg := strings.HasPrefix(s, "-")
 53		s = strings.TrimPrefix(s, "-")
 54		intPart, frac, hasDot := strings.Cut(s, ".")
 55		if intPart == "" || (hasDot && frac == "") || !digits(intPart) || !digits(frac) {
 56			return Amount{}, fmt.Errorf("%w: %q", ErrInvalidAmount, s)
 57		}
 58		if len(frac) > cur.Exponent {
 59			return Amount{}, fmt.Errorf("%w: %s allows %d, got %q", ErrPrecision, cur.Code, cur.Exponent, s)
 60		}
 61		major, err := strconv.ParseInt(intPart, 10, 64)
 62		if err != nil || major > math.MaxInt64/cur.Factor() {
 63			return Amount{}, fmt.Errorf("%w: %q out of range", ErrInvalidAmount, s)
 64		}
 65		minor := major * cur.Factor()
 66		if frac != "" {
 67			frac += strings.Repeat("0", cur.Exponent-len(frac))
 68			f, err := strconv.ParseInt(frac, 10, 64)
 69			if err != nil {
 70				return Amount{}, fmt.Errorf("%w: %q", ErrInvalidAmount, s)
 71			}
 72			minor += f
 73		}
 74		if neg {
 75			minor = -minor
 76		}
 77		return Amount{Minor: minor, Currency: cur}, nil
 78	}
 79	
 80	func digits(s string) bool {
 81		for _, r := range s {
 82			if r < '0' || r > '9' {
 83				return false
 84			}
 85		}
 86		return true
 87	}
 88	
 89	// Decimal renders the amount in major units with exactly Exponent decimals.
 90	func (a Amount) Decimal() string {
 91		m := a.Minor
 92		sign := ""
 93		if m < 0 {
 94			sign = "-"
 95			m = -m
 96		}
 97		if a.Currency.Exponent == 0 {
 98			return sign + strconv.FormatInt(m, 10)
 99		}
100		f := a.Currency.Factor()
101		return fmt.Sprintf("%s%d.%0*d", sign, m/f, a.Currency.Exponent, m%f)
102	}
103	
104	// String renders "10.50 USD".
105	func (a Amount) String() string { return a.Decimal() + " " + a.Currency.Code }
106	
107	// Add returns a+b; both must share a currency.
108	func (a Amount) Add(b Amount) (Amount, error) {
109		if a.Currency != b.Currency {
110			return Amount{}, fmt.Errorf("%w: %s + %s", ErrCurrencyMismatch, a.Currency.Code, b.Currency.Code)
111		}
112		return Amount{Minor: a.Minor + b.Minor, Currency: a.Currency}, nil
113	}
114	
115	// Sub returns a-b; both must share a currency.
116	func (a Amount) Sub(b Amount) (Amount, error) {
117		if a.Currency != b.Currency {
118			return Amount{}, fmt.Errorf("%w: %s - %s", ErrCurrencyMismatch, a.Currency.Code, b.Currency.Code)
119		}
120		return Amount{Minor: a.Minor - b.Minor, Currency: a.Currency}, nil
121	}
122	
123	// IsPositive reports whether the amount is strictly greater than zero.
124	func (a Amount) IsPositive() bool { return a.Minor > 0 }

