 74	func TestAddSub(t *testing.T) {
 75		a, b := MustNew(1000, "USD"), MustNew(250, "USD")
 76		sum, err := a.Add(b)
 77		if err != nil || sum.Minor != 1250 {
 78			t.Fatalf("Add = %v, %v", sum, err)
 79		}
 80		diff, err := a.Sub(b)
 81		if err != nil || diff.Minor != 750 {
 82			t.Fatalf("Sub = %v, %v", diff, err)
 83		}
 84		if _, err := a.Add(MustNew(1, "EUR")); !errors.Is(err, ErrCurrencyMismatch) {
 85			t.Fatalf("Add across currencies error = %v", err)
 86		}
