func TestFeeHalfToEven(t *testing.T) {
	tests := []struct {
		minor int64
		code  string
		bps   int64
		want  int64
	}{
		// Ticket example: 10.05 USD at 290 bps = 29.145 cents -> 29.
		{1005, "USD", 290, 29},
		// Strictly below / above half.
		{4999, "USD", 1, 0},
		{5001, "USD", 1, 1},
		{14999, "USD", 1, 1},
		{15001, "USD", 1, 2},
		// Exact halves (.5) round to even.
		{5000, "USD", 1, 0},    // 0.5 -> 0
		{15000, "USD", 1, 2},   // 1.5 -> 2
		{25000, "USD", 1, 2},   // 2.5 -> 2
		{35000, "USD", 1, 4},   // 3.5 -> 4
		{500, "JPY", 290, 14},  // 14.5 -> 14
		{1500, "JPY", 290, 44}, // 43.5 -> 44
		{1000, "KWD", 25, 2},   // 2.5 -> 2
		{1000, "KWD", 35, 4},   // 3.5 -> 4
	}
	for _, tt := range tests {
		got, err := Fee(MustNew(tt.minor, tt.code), tt.bps)
		if err != nil {
			t.Fatal(err)
		}
		if got.Minor != tt.want || got.Currency.Code != tt.code {
			t.Errorf("Fee(%d %s, %d bps) = %d %s, want %d %s",
				tt.minor, tt.code, tt.bps, got.Minor, got.Currency.Code, tt.want, tt.code)
		}
	}
}

func bigFeeRef(minor, bps int64) int64 {
	num := new(big.Int).Mul(big.NewInt(minor), big.NewInt(bps))
	den := big.NewInt(10000)
	q, r := new(big.Int).QuoRem(num, den, new(big.Int))
	cmp := r.Cmp(big.NewInt(5000))
	if cmp > 0 || (cmp == 0 && q.Bit(0) == 1) {
		q.Add(q, big.NewInt(1))
	}
	return q.Int64()
}

func TestFeeLargeAmounts(t *testing.T) {
	anchors := []int64{
		0,
		1,
		1005,
		9999,
		10000,
		1<<53 - 1,
		1 << 53,
		1<<53 + 1,
		math.MaxInt64 / 10000,
		math.MaxInt64 / 290,
		math.MaxInt64 - 10000,
		math.MaxInt64,
	}
	rates := []int64{0, 1, 25, 100, 290, 333, 500, 2500, 5000, 9999, 10000}

	for _, base := range anchors {
		for delta := int64(-25); delta <= 25; delta++ {
			if delta > 0 && base > math.MaxInt64-delta {
				continue
			}
			m := base + delta
			if m < 0 {
				continue
			}
			for _, bps := range rates {
				got, err := Fee(MustNew(m, "CLP"), bps)
				if err != nil {
					t.Fatalf("Fee(%d, %d): unexpected error: %v", m, bps, err)
				}
				want := bigFeeRef(m, bps)
				if got.Minor != want {
					t.Fatalf("Fee(%d, %d bps) = %d, want %d", m, bps, got.Minor, want)
				}
			}
		}
	}
}

